import KnittingInstructionActualizer, { StitchRow, KnittingInstruction } from './KnittingInstructionActualizer';

/**
 * MachineKnittingActualizer - Generates instructions tailored to knitting machines
 *
 * Supports different machine types via knittingOptions.machineType and
 * bed sizes / needle pitches via knittingOptions.maxNeedlesPerSide and knittingOptions.needlePitch.
 */
export class MachineKnittingActualizer extends KnittingInstructionActualizer {
    constructor(knittingOptions: any = {}) {
        super(knittingOptions);
        // If machineType is recognized, set sensible defaults
        if (knittingOptions && knittingOptions.machineType === 'sl1') {
            this.maxNeedlesPerSide = knittingOptions.maxNeedlesPerSide || 100;
        }
        // needlePitch can be used by higher-level instruction text; stored on knittingOptions
    }

    actualize(sectionRows: StitchRow[], baseRowIndex: number): KnittingInstruction[] {
        const instructions: KnittingInstruction[] = [];

        if (!Array.isArray(sectionRows) || sectionRows.length === 0) return instructions;

        let i = 0;
        while (i < sectionRows.length) {
            const row = sectionRows[i];

            if (row.shortRowInfo) {
                // Check if there are multiple short row sections at the same base row (mirrored pairs)
                const baseRowNumber = row.shortRowInfo.baseRowNumber;
                const shortRowSections: number[] = [i];
                
                // Look ahead to see if more short row sections share the same base row
                let k = i + 1;
                while (k < sectionRows.length) {
                    const nextRow = sectionRows[k];
                    if (nextRow.shortRowInfo && nextRow.shortRowInfo.baseRowNumber === baseRowNumber && 
                        nextRow.shortRowInfo.rowInShortRowSequence === 1) {
                        shortRowSections.push(k);
                        k++;
                    } else if (nextRow.shortRowInfo && nextRow.shortRowInfo.baseRowNumber === baseRowNumber) {
                        // Skip rows that are part of an already-detected section
                        k++;
                    } else {
                        break;
                    }
                }
                
                // Generate instructions for all short row sections at this base row
                if (shortRowSections.length > 1) {
                    this._generateMirroredShortRowInstructions(sectionRows, shortRowSections, baseRowIndex, instructions);
                } else {
                    this._generateSingleShortRowInstructions(sectionRows, shortRowSections[0], baseRowIndex, instructions);
                }
                
                // Skip all processed rows
                i = k;
                continue;
            }

            // Non-short-row: treat consecutive identical rows as a rectangular block
            let consecutive = 1;
            let prev = row;
            for (let j = i + 1; j < sectionRows.length; j++) {
                const next = sectionRows[j];
                if (next.shortRowInfo) break;
                if (next.leftStitchesInWork === prev.leftStitchesInWork && next.rightStitchesInWork === prev.rightStitchesInWork) {
                    consecutive++;
                    prev = next;
                } else break;
            }

            const lastRow = sectionRows[Math.min(sectionRows.length - 1, i + consecutive - 1)];
            const total = lastRow.leftStitchesInWork + lastRow.rightStitchesInWork;

            // Machine-specific phrasing
            const phrasing = this.knittingOptions.machineType === 'sl1' ? 'Pass yarn carriage' : 'Machine-knit';
            const instrText = `${phrasing} across ${total} needles for ${consecutive} rows. (RC=${lastRow.rowNumber})`;

            // Add per-row instructions for this block
            const stepRows: string[] = [];
            for (let k = 0; k < consecutive; k++) {
                const r = sectionRows[i + k];
                stepRows.push(`Row ${r.rowNumber}: ${phrasing} across ${r.leftStitchesInWork + r.rightStitchesInWork} needles (${r.leftStitchesInWork} left, ${r.rightStitchesInWork} right). (RC=${r.rowNumber})`);
            }

            instructions.push({
                text: instrText,
                stepData: {
                    text: instrText,
                    startRowIndex: baseRowIndex + i,
                    endRowIndex: baseRowIndex + i + consecutive - 1,
                    rowsInStep: consecutive,
                    absolutePositioning: this.getAbsolutePosition(lastRow)
                },
                rows: stepRows
            } as any);

            i += consecutive;
        }

        return instructions;
    }

    /**
     * Generate instructions for a single short row section
     * Splits into decrease phase and increase phase
     */
    private _generateSingleShortRowInstructions(sectionRows: StitchRow[], startIndex: number, baseRowIndex: number, instructions: KnittingInstruction[]): void {
        const firstShortRow = sectionRows[startIndex];
        const srInfo = firstShortRow.shortRowInfo;
        if (!srInfo) return;

        // Collect all rows in this section
        const allRows: { index: number; activeStitches: number; row: StitchRow }[] = [];
        for (let k = 0; k < srInfo.totalRowsInShortRow; k++) {
            if (startIndex + k < sectionRows.length) {
                const r = sectionRows[startIndex + k];
                if (r.shortRowInfo && r.shortRowInfo.shortRowId === srInfo.shortRowId) {
                    const activeStitches = r.shortRowInfo.activeStitchesLeft + r.shortRowInfo.activeStitchesRight;
                    allRows.push({ index: k, activeStitches, row: r });
                }
            }
        }

        if (allRows.length === 0) return;

        // Find the turning point (minimum active stitches)
        let minActiveStitches = allRows[0].activeStitches;
        let turningPointIndex = 0;

        for (let i = 0; i < allRows.length; i++) {
            if (allRows[i].activeStitches <= minActiveStitches) {
                minActiveStitches = allRows[i].activeStitches;
                turningPointIndex = i;
            }
        }

        // Split into decrease and increase phases
        const decreaseRows = allRows.slice(0, turningPointIndex + 1);
        const increaseRows = allRows.slice(turningPointIndex + 1);

        const label = srInfo.shortRowLabel || 'short row';
        const isRightSide = (srInfo.posX ?? 0.5) > 0.5;
        const sideLabel = isRightSide ? 'right' : 'left';

        // Generate DECREASE PHASE instruction
        if (decreaseRows.length > 0) {
            const decreaseStartStitches = decreaseRows[0].activeStitches;
            const decreaseEndStitches = decreaseRows[decreaseRows.length - 1].activeStitches;
            const firstDecreaseRow = decreaseRows[0].row;
            const lastDecreaseRow = decreaseRows[decreaseRows.length - 1].row;

            let decreaseInstr = `SHORT ROW SECTION (${sideLabel}) - DECREASE PHASE:\n\n`;

            // Transfer instruction
            if (srInfo.heldStitchesLeft > 0 || srInfo.heldStitchesRight > 0) {
                decreaseInstr += 'TRANSFER: ';
                if (srInfo.heldStitchesLeft > 0) {
                    decreaseInstr += `${srInfo.heldStitchesLeft} needle${srInfo.heldStitchesLeft > 1 ? 's' : ''} on left to hold. `;
                }
                if (srInfo.heldStitchesRight > 0) {
                    decreaseInstr += `${srInfo.heldStitchesRight} needle${srInfo.heldStitchesRight > 1 ? 's' : ''} on right to hold. `;
                }
                decreaseInstr += '\n';
            }

            // Knit instruction
            decreaseInstr += 'KNIT: ';
            if (decreaseStartStitches === decreaseEndStitches) {
                decreaseInstr += `${decreaseRows.length} row${decreaseRows.length > 1 ? 's' : ''} across ${decreaseStartStitches} needles. `;
            } else {
                decreaseInstr += `${decreaseRows.length} row${decreaseRows.length > 1 ? 's' : ''}, working ${decreaseStartStitches} down to ${decreaseEndStitches} needles. `;
            }
            decreaseInstr += `(RC=${firstDecreaseRow.rowNumber}${lastDecreaseRow.rowNumber !== firstDecreaseRow.rowNumber ? '-' + lastDecreaseRow.rowNumber : ''})`;

            // Row-by-row instructions
            const decreaseRowInstructions: string[] = [];
            for (const { index, row } of decreaseRows) {
                const rowSrInfo = row.shortRowInfo;
                if (rowSrInfo) {
                    const rowActiveStitches = rowSrInfo.activeStitchesLeft + rowSrInfo.activeStitchesRight;
                    decreaseRowInstructions.push(`Row ${baseRowIndex + startIndex + index + 1}: Knit ${rowActiveStitches} needles. (RC=${row.rowNumber})`);
                }
            }

            instructions.push({
                text: decreaseInstr.trim(),
                stepData: {
                    text: decreaseInstr.trim(),
                    startRowIndex: baseRowIndex + startIndex,
                    endRowIndex: baseRowIndex + startIndex + decreaseRows[decreaseRows.length - 1].index,
                    rowsInStep: decreaseRows.length,
                    absolutePositioning: this.getAbsolutePosition(firstDecreaseRow)
                },
                rows: decreaseRowInstructions
            } as any);
        }

        // Generate INCREASE PHASE instruction
        if (increaseRows.length > 0) {
            const increaseStartStitches = increaseRows[0].activeStitches;
            const increaseEndStitches = increaseRows[increaseRows.length - 1].activeStitches;
            const firstIncreaseRow = increaseRows[0].row;
            const lastIncreaseRow = increaseRows[increaseRows.length - 1].row;

            let increaseInstr = `SHORT ROW SECTION (${sideLabel}) - INCREASE PHASE:\n\n`;
            increaseInstr += 'RETURN: Bring held needles back into work.\n';
            increaseInstr += 'KNIT: ';

            if (increaseStartStitches === increaseEndStitches) {
                increaseInstr += `${increaseRows.length} row${increaseRows.length > 1 ? 's' : ''} across ${increaseStartStitches} needles. `;
            } else {
                increaseInstr += `${increaseRows.length} row${increaseRows.length > 1 ? 's' : ''}, working ${increaseStartStitches} up to ${increaseEndStitches} needles. `;
            }
            increaseInstr += `(RC=${firstIncreaseRow.rowNumber}${lastIncreaseRow.rowNumber !== firstIncreaseRow.rowNumber ? '-' + lastIncreaseRow.rowNumber : ''})`;

            // Row-by-row instructions
            const increaseRowInstructions: string[] = [];
            for (const { index, row } of increaseRows) {
                const rowSrInfo = row.shortRowInfo;
                if (rowSrInfo) {
                    const rowActiveStitches = rowSrInfo.activeStitchesLeft + rowSrInfo.activeStitchesRight;
                    increaseRowInstructions.push(`Row ${baseRowIndex + startIndex + index + 1}: Knit ${rowActiveStitches} needles. (RC=${row.rowNumber})`);
                }
            }

            instructions.push({
                text: increaseInstr.trim(),
                stepData: {
                    text: increaseInstr.trim(),
                    startRowIndex: baseRowIndex + startIndex + increaseRows[0].index,
                    endRowIndex: baseRowIndex + startIndex + increaseRows[increaseRows.length - 1].index,
                    rowsInStep: increaseRows.length,
                    absolutePositioning: this.getAbsolutePosition(firstIncreaseRow)
                },
                rows: increaseRowInstructions
            } as any);
        }
    }

    /**
     * Generate instructions for multiple short row sections at the same base row (mirrored pairs)
     * Each section gets BOTH decrease and increase phases
     */
    private _generateMirroredShortRowInstructions(sectionRows: StitchRow[], startIndices: number[], baseRowIndex: number, instructions: KnittingInstruction[]): void {
        // For each section, generate decrease and increase phases
        startIndices.forEach(startIdx => {
            this._generateSingleShortRowInstructions(sectionRows, startIdx, baseRowIndex, instructions);
        });
    }
}

export default MachineKnittingActualizer;
